/* AXIS 토큰: 기본 CSS 변수(--axis-*)와 shadcn 호환 변수(--background · --primary 등). @import 는 @tailwind 보다 앞에 둡니다 */
@import "@axis-ds/tokens/css";
@import "@axis-ds/tokens/css/shadcn";
/* ontology 브랜드: 아래 줄의 주석을 풀고 app/layout.tsx 의 <html> 에 data-brand="ontology" 를 넣습니다 */
/* @import "@axis-ds/tokens/css/brands/ontology"; */

@tailwind base;
@tailwind components;
@tailwind utilities;

/*
 * 테두리 기본색: Tailwind 3 preflight 의 `* { border-color: gray-200 }` 가 shadcn 호환 CSS 의 `* { border-color }` 보다
 * 뒤에 와서 이기므로, `border` 클래스가 다크 · 브랜드에서도 회색으로 남지 않게 AXIS --border 로 되돌립니다
 */
@layer base {
  * {
    @apply border-border;
  }
}

import type { Metadata } from 'next'
// AXIS 대표 글꼴 Pretendard(동적 서브셋). 글꼴 스택은 AXIS preset 이 <html> 에 적용합니다
import 'pretendard/dist/web/variable/pretendardvariable-dynamic-subset.css'
import './globals.css'

export const metadata: Metadata = {
  title: 'AXIS Dashboard',
  description: 'AXIS 디자인 시스템 기반 대시보드',
}

// ontology 브랜드를 켜려면 globals.css 의 브랜드 import 주석을 풀고 <html> 에 data-brand="ontology" 를 넣습니다
export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="ko" suppressHydrationWarning>
      <body>{children}</body>
    </html>
  )
}

'use client'

const navItems = [
  { label: '대시보드', href: '/', active: true },
  { label: '분석', href: '/analytics', active: false },
  { label: '사용자', href: '/users', active: false },
  { label: '설정', href: '/settings', active: false },
]

export function Sidebar() {
  return (
    <aside className="hidden lg:flex w-64 flex-col border-r bg-card">
      <div className="p-6">
        <h2 className="text-lg font-bold">AXIS Dashboard</h2>
      </div>

      <nav className="flex-1 px-4 space-y-1">
        {navItems.map((item) => (
          <a
            key={item.label}
            href={item.href}
            className={`flex items-center rounded-md px-3 py-2 text-sm font-medium transition-colors ${
              item.active
                ? 'bg-accent text-accent-foreground'
                : 'text-muted-foreground hover:bg-accent hover:text-accent-foreground'
            }`}
          >
            {item.label}
          </a>
        ))}
      </nav>

      <div className="border-t p-4">
        <p className="text-xs text-muted-foreground">AXIS Design System v0.7</p>
      </div>
    </aside>
  )
}

interface StatsCardProps {
  title: string
  value: string
  change: string
  trend: 'up' | 'down'
}

export function StatsCard({ title, value, change, trend }: StatsCardProps) {
  return (
    <div className="rounded-lg border bg-card p-4 text-card-foreground">
      <p className="text-sm text-muted-foreground">{title}</p>
      <p className="text-2xl font-bold mt-1">{value}</p>
      <p
        className={`text-xs mt-1 ${
          trend === 'up'
            ? 'text-[var(--axis-status-success-strong)] dark:text-[var(--axis-status-success)]'
            :'text-[var(--axis-status-error-strong)] dark:text-[var(--axis-status-error)]'
        }`}
      >
        {change}
      </p>
    </div>
  )
}

/** Tailwind 3 를 PostCSS 플러그인으로 돌립니다(없으면 @tailwind 지시문이 그대로 남아 유틸리티가 생성되지 않음, WI-0037) */
export default {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
}

import type { Config } from 'tailwindcss'
import axisPreset from '@axis-ds/tokens/tailwind'

/** 색 · 둥글기 · 글꼴(Pretendard 스택) · darkMode 는 AXIS preset 이 정합니다 */
const config: Config = {
  presets: [axisPreset],
  content: ['./app/**/*.{ts,tsx}', './components/**/*.{ts,tsx}'],
  plugins: [],
}

export default config
